 // buildHookSpecs returns the hook specifications for all managed hooks.
@@ -244,31 +347,39 @@ func buildHookSpecs(cmdPrefix string) []hookSpec {
 	}
 }

+// gitHookCommand wraps an invocation in an existence test, so a hook whose
