 func gitHookCommand(cmdPrefix, args string, warnMissing bool) string {
 	invocation := fmt.Sprintf("%s hooks git %s", cmdPrefix, args)
-	availableTest, ok := gitHookCommandAvailableTest(cmdPrefix)
